---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Context meter: How full the context is and what fills it, with Compact to free room.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change context-meter.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './context-meter.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="context-meter" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ctm" data-open="1" data-pos="up">
  <button class="ctm-tg" aria-expanded="true" aria-label="Context"><span class="ctm-ring" aria-hidden="true"><svg viewBox="0 0 20 20"><circle class="tr" cx="10" cy="10" r="7.5"/><circle class="fl" cx="10" cy="10" r="7.5" pathLength="100"/><circle class="fw" cx="10" cy="10" r="7.5" pathLength="100"/><circle class="hl" cx="10" cy="10" r="7.5" pathLength="100"/></svg></span><span><span class="ctm-pc num">0%</span> of context used</span><svg class="i xs"><use href="#i-chev-d"/></svg></button>
  <div class="ctm-pop panel" role="region" aria-label="What fills the context">
    <div class="ctm-ph"><span>In context</span><span class="num"><b class="ctm-tot">0k</b> of 200k tokens</span></div>
    <div class="ctm-bar" aria-hidden="true"></div>
    <div class="ctm-leg mx-glide"></div>
    <div class="ctm-msg" aria-live="polite"><span></span></div>
    <div class="ctm-f"><span class="ctm-hint">Summarises older turns</span><button class="pill line sm ctm-go mx-press">Compact</button></div>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './context-meter.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Context meter ---------- */
/* a pill with the ring opens what fills the context: one bar split by kind, a legend whose rows list their items, and Compact */
/* it never anchors the page's scroll, so the page can't follow it as it changes; on a card it sits in the middle of its room */
/* the panel opens above the pill, as it does under a chat composer (owner, 26 Nov), and below it only where there is no room
   above (data-pos="down", set as it opens). The pill comes first for the keyboard and the panel is drawn above it. On a card
   the two sit centred together: the pill rests in the middle and glides down as the panel opens over it */
.ctm{display:flex;flex-direction:column-reverse;align-items:flex-start;justify-content:center;gap:var(--dm-s-2);width:100%;max-width:340px;margin-inline:auto;overflow-anchor:none}
.stage-in:has(>.ctm){overflow-anchor:none}
.stage-in>.ctm{min-height:inherit}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov) */
.ctm :is(.pill,.ib,.ctm-tg):active{transform:none}
.ctm[data-pos="down"]{flex-direction:column}
.ctm-tg{display:inline-flex;align-items:center;gap:var(--dm-s-2);height:32px;padding:0 10px 0 7px;border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:var(--dm-shadow);transition:box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ctm-tg:hover{box-shadow:var(--dm-shadow-pop)}}
.ctm-tg .ctm-pc{color:var(--dm-fg);font-weight:500}
.ctm-tg>svg:last-child{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
/* the chevron points the way the panel opens while it is shut, and turns over once it is open: up, then down (as Run drawer's
   does); below, it is the usual down, then up */
.ctm[data-open="0"]:not([data-pos="down"]) .ctm-tg>svg:last-child,.ctm[data-pos="down"][data-open="1"] .ctm-tg>svg:last-child{transform:rotate(180deg)}
/* shut, the panel folds away to nothing (owner, 17 Nov: no room kept for a later state): its height eases to 0 as it fades,
   so the meter shrinks with it and stays centred in its stage, and opens back the same way. Where the browser can't ease a
   height to auto, it opens and shuts at once. It only fades as its height eases, with no glide on top (owner, 19 Nov). Its
   content sits 16px in from every edge (owner, 18 Nov). It grows out of the pill: its edge next to the pill stays put, its
   content holds to that edge as the far one eases out, and it scales a little from the pill's corner as it fades */
.ctm{interpolate-size:allow-keywords}
.ctm-pop{width:100%;min-height:0;padding:var(--dm-s-4);display:flex;flex-direction:column;justify-content:flex-end;gap:var(--dm-s-3);overflow:clip;transform-origin:0 100%;transition:opacity .32s var(--dm-ease),transform .42s var(--dm-ease),height .42s var(--dm-ease),margin .42s var(--dm-ease),padding .42s var(--dm-ease),visibility 0s}
.ctm[data-pos="down"] .ctm-pop{justify-content:flex-start;transform-origin:0 0}
.ctm[data-open="0"] .ctm-pop{height:0;margin-bottom:calc(-1 * var(--dm-s-2));padding-block:0;opacity:0;transform:scale(.98);visibility:hidden;pointer-events:none;transition:opacity .16s var(--dm-ease),transform .32s var(--dm-ease),height .32s var(--dm-ease),margin .32s var(--dm-ease),padding .32s var(--dm-ease),visibility 0s .32s}
.ctm[data-pos="down"][data-open="0"] .ctm-pop{margin-bottom:0;margin-top:calc(-1 * var(--dm-s-2))}
@media (prefers-reduced-motion:reduce){.ctm-pop,.ctm[data-open="0"] .ctm-pop{transition:none}}
.ctm-ph{display:flex;align-items:baseline;justify-content:space-between;gap:var(--dm-s-3);font-size:13px;line-height:18px;color:var(--dm-muted)}
.ctm-ph b{color:var(--dm-fg);font-weight:500}
/* the bar: one part per kind in the chart palette (the accent first, a neutral grey for the quiet part), on the neutral rail */
.ctm-bar{display:flex;gap:2px;height:8px;border-radius:var(--dm-r-xs);background:var(--dm-rail);overflow:hidden}
.ctm-bar i{height:100%;width:0;flex:none;background:var(--dm-c);transition:width .42s var(--dm-ease),opacity .16s}
.ctm-bar.hl i:not(.on){opacity:.25}
/* the legend's rows answer the pointer: the swatch sits on the content's edge and the hover reaches out round it */
/* (the swatches start and the values end on the content's 16px column, as the head's words do; a row's hover fill reaches
   8px out round it, into the padding (owner, 26 Nov)) */
.ctm-leg{display:flex;flex-direction:column;margin:0 calc(-1 * var(--dm-s-2))}
.ctm-l{display:flex;align-items:center;gap:var(--dm-s-2);padding:5px var(--dm-s-2);border-radius:var(--dm-r-sm);font-size:13px;line-height:18px;color:var(--dm-fg2);cursor:default;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ctm-l:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}}
/* its motion (the core's motion pieces, owner, 26 Nov): one highlight glides from part to part in the legend, in the hover's
   own grey (.mx-glide); a press on Compact shows at once; its box eases to its new words' width on the spring (mxWidth()) */
.ctm-leg{--dm-hg-bg:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
:root[data-style="clean"] .ctm-leg,:root [data-style="clean"] .ctm-leg,:root [data-style="clean"].ctm-leg{--dm-hg-bg:var(--dm-row)}
/* the swatch is centred in a 16px column, the column of the message's sign and tick below, so their words line up */
.ctm-l .sw{width:8px;height:8px;margin:0 4px 0 0;border-radius:var(--dm-r-tiny,2px);flex:none;background:var(--dm-c)}
.ctm-l .v{margin-left:auto;color:var(--dm-fg)}
/* the message takes no room until it has something to say (owner, 17 Nov), and opens smoothly when it does. A warning is a
   warning notice (owner, 18 Nov): a faint warning tint, the filled warning sign in the warning mark and the words in the text
   colour; the action that resolves it is Compact, below, in the warning tint while it shows. A result is a plain line with
   the green tick */
.ctm-msg{display:grid;grid-template-rows:0fr;margin-top:calc(-1 * var(--dm-s-3));font-size:13px;line-height:18px;color:var(--dm-fg);opacity:0;transition:grid-template-rows .32s var(--dm-ease),margin .32s var(--dm-ease),opacity .24s var(--dm-ease)}
.ctm-msg.on{grid-template-rows:1fr;margin-top:0;opacity:1}
.ctm-msg>span{display:flex;align-items:flex-start;gap:var(--dm-s-2);min-height:0;overflow:hidden}
/* (the warning's tint and padding ease away as it turns into the result, so the panel eases to its new height in one motion) */
.ctm-msg>span{transition:padding .32s var(--dm-ease),background-color .32s var(--dm-ease)}
.ctm-msg>span>svg,.ctm-msg>span>svg.i{flex:none;width:16px;height:16px;margin-top:1px}
/* the notice reaches out as far as the legend's hover, with the legend's padding, so its sign sits in the swatches' column
   and its words on the legend's words */
/* (a message's mark sits on the legend's swatch column and its words on the legend's words; the warning's tint is as wide
   as the content, its words 6px inside it) */
.ctm-msg:not(.warn)>span{padding-inline:6px}
.ctm-msg.warn>span{margin:0;padding:8px 6px;border-radius:var(--dm-r-sm);background:color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)}
.ctm-wi{overflow:visible}
.ctm-wi .a{fill:var(--dm-warn-mark);stroke:var(--dm-warn-mark);stroke-width:2;stroke-linejoin:round}
.ctm-wi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.ctm-msg.ok>span>svg{color:var(--dm-ok-mark)}
@media (prefers-reduced-motion:reduce){.ctm-msg{transition:none}}
.ctm-f{display:flex;align-items:center;gap:10px;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ctm-go{overflow:hidden;white-space:nowrap;justify-content:flex-start}
/* while it compacts nothing can be pressed, so it says so where the button was (owner, 21 Nov: "should this be gray button?
   especially the loading animation?"): the spinner in the accent and the words in the loader's sweep, as plain words, the row
   keeping its height and its right edge; Undo comes in once it is done */
.ctm-run{display:inline-flex;align-items:center;gap:6px;height:28px;flex:none;font-size:13px;color:var(--dm-fg);white-space:nowrap}
.ctm-run[hidden]{display:none}
.ctm-run .spin{width:12px;height:12px;color:var(--dm-accent-mark,var(--dm-accent))}
.ctm-f .ctm-hint{flex:1;min-width:0;font-size:13px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the ring: inside the meter's pill, and as its own button where Agent harness puts it in the composer. Its track is the
   neutral rail and its fill the accent's mark colour (3:1), the warning mark near the limit */
.ctm-ft{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px;color:var(--dm-fg2)}
.ctm-ring{width:30px;height:30px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;flex:none;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.ctm-ring:hover{background:var(--dm-row)}}
.ctm-tg .ctm-ring{width:20px;height:20px;background:none}
.ctm-ring svg{width:18px;height:18px;transform:rotate(-90deg);overflow:visible}
.ctm-ring circle{fill:none;stroke-width:2.6}
.ctm-ring .tr{stroke:var(--dm-rail)}
.ctm-ring .fl{stroke:var(--dm-accent-mark,var(--dm-accent));stroke-linecap:round;stroke-dasharray:0 100;transition:stroke-dasharray .42s var(--dm-ease),stroke .32s}
/* near the limit the ring turns to the warning mark by a wipe, never a blend (owner, 26 Nov, from its showcase): a second arc in
   the warning mark (.fw) draws along the accent's from its start in 200ms, and draws back the same way once it is compacted, so
   no frame shows a mix of the two colours. Each step up sends a thin bright highlight once along the filled arc (.hl, 0.45s)
   and lifts the ring a touch (1.06, 0.35s); crossing the limit nudges the pill once. No halo or glow round it. With reduced
   motion the ring and its colour change at once, with no highlight, lift or nudge */
.ctm-ring .fw{stroke:var(--dm-warn-mark);stroke-linecap:round;stroke-dasharray:0 100;opacity:0;transition:stroke-dasharray .42s var(--dm-ease)}
.ctm-ring .hl{stroke:#fff;stroke-width:2;stroke-linecap:butt;stroke-dasharray:0 200;opacity:0}

/* Clean (owner, 17 and 18 Nov): the pill is the flat secondary control (a hairline and a light fill, no press); the ring is
   the accent's mark on a grey rail. The panel is a 22px card with an off-white head strip and foot strip, opening and
   shutting with a fade and a slight scale from the pill, no move or blur, its content 16px in from every edge: the legend's rows sit 8px in with 8px of their
   own, their hover concentric with the card's corners, and Compact is a 28px secondary pill 16px from the foot's side, bottom
   and hairline (owner, 23 Nov). The
   parts of the bar keep their colours */
:root[data-style="clean"] .ctm-tg,:root [data-style="clean"] .ctm-tg,:root [data-style="clean"].ctm-tg{height:32px;border-radius:var(--dm-r-pill);color:var(--dm-fg2);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ctm-tg:hover,:root [data-style="clean"] .ctm-tg:hover,:root [data-style="clean"].ctm-tg:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .ctm-tg:active,:root [data-style="clean"] .ctm-tg:active,:root [data-style="clean"].ctm-tg:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .ctm-ring .tr,:root [data-style="clean"] .ctm-ring .tr,:root [data-style="clean"].ctm-ring .tr{stroke:var(--dm-rail)}
:root[data-style="clean"] .ctm-pop,:root [data-style="clean"] .ctm-pop,:root [data-style="clean"].ctm-pop{padding:0;gap:0;transition:opacity .22s var(--dm-ease),transform .32s var(--dm-ease),height .32s var(--dm-ease),margin .32s var(--dm-ease),visibility 0s}
:root[data-style="clean"] .ctm[data-open="0"] .ctm-pop,:root [data-style="clean"] .ctm[data-open="0"] .ctm-pop,:root [data-style="clean"].ctm[data-open="0"] .ctm-pop{transition:opacity .15s var(--dm-ease),transform .2s var(--dm-ease),height .24s var(--dm-ease),margin .24s var(--dm-ease),visibility 0s .24s}
:root[data-style="clean"] .ctm-ph,:root [data-style="clean"] .ctm-ph,:root [data-style="clean"].ctm-ph{padding:calc(var(--dm-strip-y) + 5px) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);font-size:12.5px;line-height:18px}
:root[data-style="clean"] .ctm-bar,:root [data-style="clean"] .ctm-bar,:root [data-style="clean"].ctm-bar{margin:16px 16px 0;height:6px;gap:2px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-rail)}
:root[data-style="clean"] .ctm-bar i,:root [data-style="clean"] .ctm-bar i,:root [data-style="clean"].ctm-bar i{transition:width .42s var(--dm-ease),opacity .15s var(--dm-ease)}
:root[data-style="clean"] .ctm-bar i:first-child,:root [data-style="clean"] .ctm-bar i:first-child,:root [data-style="clean"].ctm-bar i:first-child{border-radius:3px 0 0 3px}
:root[data-style="clean"] .ctm-bar.hl i:not(.on),:root [data-style="clean"] .ctm-bar.hl i:not(.on),:root [data-style="clean"].ctm-bar.hl i:not(.on){opacity:.28}
:root[data-style="clean"] .ctm-leg,:root [data-style="clean"] .ctm-leg,:root [data-style="clean"].ctm-leg{margin:8px 8px 0}
:root[data-style="clean"] .ctm-l,:root [data-style="clean"] .ctm-l,:root [data-style="clean"].ctm-l{padding:5px 8px;border-radius:calc(var(--dm-r-card) - 8px);transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ctm-l:hover,:root [data-style="clean"] .ctm-l:hover,:root [data-style="clean"].ctm-l:hover{background:var(--dm-row)}}
:root[data-style="clean"] .ctm-msg,:root [data-style="clean"] .ctm-msg,:root [data-style="clean"].ctm-msg{margin:0 16px}
:root[data-style="clean"] .ctm-msg.on,:root [data-style="clean"] .ctm-msg.on,:root [data-style="clean"].ctm-msg.on{margin:8px 16px 5px}
:root[data-style="clean"] .ctm-msg:not(.warn)>span,:root [data-style="clean"] .ctm-msg:not(.warn)>span,:root [data-style="clean"].ctm-msg:not(.warn)>span{padding-inline:8px}
:root[data-style="clean"] .ctm-msg.warn>span,:root [data-style="clean"] .ctm-msg.warn>span,:root [data-style="clean"].ctm-msg.warn>span{margin:0;padding:8px;border-radius:calc(var(--dm-r-card) - 8px)}
:root[data-style="clean"] .ctm-f,:root [data-style="clean"] .ctm-f,:root [data-style="clean"].ctm-f{margin-top:11px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
